    // Fresh ids per seed so canvas keys stay unique across re-seeds
    const raw = {"id": "devils_atlas_example", "title": "The Devil's Atlas", "theme": "conspiracy", "created": "2026-08-06T00:00:00.000Z", "pages": [{"id": 1000000000015, "background": "#0a0505", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0001", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "fire", "opacity": 0.45}, {"id": "da_0002", "type": "image", "zIndex": 1, "x": -40, "y": -20, "width": 280, "height": 280, "src": "/assets/devils-atlas/blood-splat00.png", "objectFit": "cover", "opacity": 0.85, "rotation": -15, "blendMode": "screen"}, {"id": "da_0003", "type": "image", "zIndex": 1, "x": 300, "y": 520, "width": 260, "height": 260, "src": "/assets/devils-atlas/blood-splat30.png", "objectFit": "cover", "opacity": 0.7, "rotation": 25, "blendMode": "screen"}, {"id": "da_0004", "type": "image", "zIndex": 1, "x": 180, "y": 200, "width": 200, "height": 200, "src": "/assets/devils-atlas/ink-splat12.png", "objectFit": "cover", "opacity": 0.5, "rotation": 40}, {"id": "da_0005", "type": "panel", "zIndex": 2, "x": 36, "y": 36, "width": 456, "height": 744, "fill": "transparent", "panelBorderWidth": 3, "panelBorderColor": "#c5b358", "panelRadius": 0}, {"id": "da_0006", "type": "panel", "zIndex": 2, "x": 48, "y": 48, "width": 432, "height": 720, "fill": "transparent", "panelBorderWidth": 1, "panelBorderColor": "#4a0000", "panelRadius": 0}, {"id": "da_0007", "type": "text", "zIndex": 3, "x": 234, "y": 90, "width": 60, "height": 50, "content": "👁", "fontSize": 36, "align": "center", "color": "#c5b358", "animation": "pulse", "animDuration": 2.5, "animLoop": true}, {"id": "da_0008", "type": "text", "zIndex": 3, "x": 64, "y": 150, "width": 400, "height": 24, "content": "CLASSIFIED // THREAD MANIFEST", "fontFamily": "Courier Prime", "fontSize": 11, "color": "#00ff00", "align": "center", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0009", "type": "text", "zIndex": 4, "x": 40, "y": 200, "width": 448, "height": 140, "content": "THE DEVIL'S\nATLAS", "fontFamily": "Cinzel", "fontSize": 52, "color": "#e8e4d9", "align": "center", "bold": true, "textShadow": "4px 4px 0 #4a0000", "lineHeight": 1.05}, {"id": "da_0010", "type": "text", "zIndex": 4, "x": 50, "y": 360, "width": 428, "height": 70, "content": "How I Lost Everything and Drove\nto Mongolia in Ninety Minutes", "fontFamily": "Special Elite", "fontSize": 15, "color": "#c5b358", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0011", "type": "shape", "zIndex": 3, "x": 140, "y": 450, "width": 248, "height": 2, "shape": "line_h", "fill": "#c5b358", "opacity": 0.7}, {"id": "da_0012", "type": "text", "zIndex": 4, "x": 40, "y": 480, "width": 448, "height": 28, "content": "John J. Smith", "fontFamily": "EB Garamond", "fontSize": 16, "color": "#e8e4d9", "align": "center", "lineHeight": 1.35}, {"id": "da_0013", "type": "text", "zIndex": 4, "x": 40, "y": 510, "width": 448, "height": 24, "content": "Illustrated by Kyle Derby MacInnis", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#7f8c8d", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0014", "type": "text", "zIndex": 5, "x": 144, "y": 620, "width": 240, "height": 44, "content": "OPEN THE ATLAS →", "action": "goto", "actionVal": "2", "fontFamily": "Special Elite", "fontSize": 15, "color": "#0a0505", "align": "center", "bold": true, "fill": "#c5b358", "borderRadius": 4, "animation": "pulse", "animDuration": 2, "animLoop": true}, {"id": "da_0015", "type": "text", "zIndex": 4, "x": 40, "y": 740, "width": 448, "height": 20, "content": "Void Press Showcase  ·  Issue Zero", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#555", "align": "center", "lineHeight": 1.35}], "bgm": "gen:horror"}, {"id": 1000000000021, "background": "#1a1208", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0016", "type": "text", "zIndex": 2, "x": 40, "y": 80, "width": 448, "height": 40, "content": "DEDICATION", "fontFamily": "Cinzel", "fontSize": 22, "color": "#c5b358", "align": "center", "bold": true}, {"id": "da_0017", "type": "text", "zIndex": 2, "x": 60, "y": 160, "width": 408, "height": 160, "content": "For everyone who ever felt like the world was wrong.\n\nYou weren't crazy.\nYou were just tuned.", "fontFamily": "EB Garamond", "fontSize": 18, "color": "#e8e4d9", "align": "center", "lineHeight": 1.4, "italic": true}, {"id": "da_0018", "type": "shape", "zIndex": 1, "x": 160, "y": 360, "width": 208, "height": 1, "shape": "line_h", "fill": "#c5b358", "opacity": 0.5}, {"id": "da_0019", "type": "text", "zIndex": 2, "x": 40, "y": 400, "width": 448, "height": 28, "content": "HOW TO READ THIS ZINE", "fontFamily": "Special Elite", "fontSize": 14, "color": "#c5b358", "align": "center", "lineHeight": 1.35}, {"id": "da_0020", "type": "text", "zIndex": 2, "x": 50, "y": 440, "width": 428, "height": 220, "content": "Tap gold buttons to jump. Tap flash/VFX buttons for effects. Tap \"REVEAL\" to uncover hidden seams. One page is locked — password: seam\n\nEvery element here was placed with the native editor: text, panels, balloons, shapes, shaders, symbols, SFX type, images, animations, blend modes, and logic actions.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#bbb", "align": "center", "lineHeight": 1.4}, {"id": "da_0021", "type": "text", "zIndex": 3, "x": 134, "y": 700, "width": 260, "height": 40, "content": "BEGIN THE FOREWORD →", "action": "goto", "actionVal": "3", "fontFamily": "Special Elite", "fontSize": 14, "color": "#000", "align": "center", "bold": true, "fill": "#c5b358", "borderRadius": 4}]}, {"id": 1000000000034, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0022", "type": "image", "zIndex": 0, "x": 340, "y": -40, "width": 220, "height": 220, "src": "/assets/devils-atlas/ink-splat05.png", "objectFit": "cover", "opacity": 0.35, "rotation": 20}, {"id": "da_0023", "type": "text", "zIndex": 2, "x": 40, "y": 40, "width": 448, "height": 40, "content": "CONTENTS", "fontFamily": "Special Elite", "fontSize": 32, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0024", "type": "shape", "zIndex": 1, "x": 40, "y": 90, "width": 448, "height": 2, "shape": "line_h", "fill": "#4a0000"}, {"id": "da_0025", "type": "text", "zIndex": 2, "x": 40, "y": 120, "width": 448, "height": 36, "content": "I.  FOREWORD — The Road Less Traveled", "action": "goto", "actionVal": "4", "fontFamily": "Special Elite", "fontSize": 13, "color": "#c5b358", "align": "left", "bold": true, "fill": "#1a1a1a", "borderRadius": 4}, {"id": "da_0026", "type": "text", "zIndex": 2, "x": 40, "y": 170, "width": 448, "height": 36, "content": "II. PART ONE — The Slide", "action": "goto", "actionVal": "7", "fontFamily": "Special Elite", "fontSize": 13, "color": "#c5b358", "align": "left", "bold": true, "fill": "#1a1a1a", "borderRadius": 4}, {"id": "da_0027", "type": "text", "zIndex": 2, "x": 40, "y": 220, "width": 448, "height": 36, "content": "III. PART TWO — The Seam", "action": "goto", "actionVal": "15", "fontFamily": "Special Elite", "fontSize": 13, "color": "#c5b358", "align": "left", "bold": true, "fill": "#1a1a1a", "borderRadius": 4}, {"id": "da_0028", "type": "text", "zIndex": 2, "x": 40, "y": 270, "width": 448, "height": 36, "content": "IV. PART THREE — The Weave", "action": "goto", "actionVal": "19", "fontFamily": "Special Elite", "fontSize": 13, "color": "#c5b358", "align": "left", "bold": true, "fill": "#1a1a1a", "borderRadius": 4}, {"id": "da_0029", "type": "text", "zIndex": 2, "x": 40, "y": 320, "width": 448, "height": 36, "content": "V.  EPILOGUE — The Weave Continues", "action": "goto", "actionVal": "23", "fontFamily": "Special Elite", "fontSize": 13, "color": "#c5b358", "align": "left", "bold": true, "fill": "#1a1a1a", "borderRadius": 4}, {"id": "da_0030", "type": "panel", "zIndex": 1, "x": 40, "y": 400, "width": 448, "height": 160, "fill": "#1c1c1c", "panelBorderWidth": 2, "panelBorderColor": "#c5b358", "panelRadius": 0}, {"id": "da_0031", "type": "text", "zIndex": 2, "x": 60, "y": 430, "width": 50, "height": 50, "content": "🧭", "fontSize": 36, "align": "center", "color": "#c5b358"}, {"id": "da_0032", "type": "text", "zIndex": 2, "x": 120, "y": 420, "width": 340, "height": 130, "content": "The maps are wrong. The GPS is a tool of mass deception. Somewhere past the edges you were handed in grade school, there are seams.\n\nIf you find one — keep driving.", "fontFamily": "Special Elite", "fontSize": 12, "color": "#e8e4d9", "align": "left", "lineHeight": 1.4}, {"id": "da_0033", "type": "text", "zIndex": 2, "x": 40, "y": 620, "width": 448, "height": 30, "content": "Zen is hungry. Zen is always hungry.", "fontFamily": "EB Garamond", "fontSize": 14, "color": "#4a0000", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0034", "type": "text", "zIndex": 3, "x": 164, "y": 700, "width": 200, "height": 40, "content": "TURN THE PAGE →", "action": "goto", "actionVal": "4", "fontFamily": "Special Elite", "fontSize": 14, "color": "#000", "align": "center", "bold": true, "fill": "#c5b358", "borderRadius": 4}]}, {"id": 1000000000040, "background": "#1a1008", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0035", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "fire", "opacity": 0.3}, {"id": "da_0036", "type": "image", "zIndex": 1, "x": 0, "y": 0, "width": 528, "height": 280, "src": "/assets/devils-atlas/sky-wrong.jpg", "objectFit": "cover", "opacity": 0.55, "blendMode": "overlay"}, {"id": "da_0037", "type": "text", "zIndex": 3, "x": 40, "y": 40, "width": 448, "height": 24, "content": "FOREWORD", "fontFamily": "Courier Prime", "fontSize": 11, "color": "#c5b358", "align": "center", "lineHeight": 1.35, "letterSpacing": 4}, {"id": "da_0038", "type": "text", "zIndex": 3, "x": 40, "y": 70, "width": 448, "height": 90, "content": "THE ROAD\nLESS TRAVELED", "fontFamily": "Cinzel", "fontSize": 28, "color": "#e8e4d9", "align": "center", "bold": true}, {"id": "da_0039", "type": "panel", "zIndex": 2, "x": 36, "y": 300, "width": 456, "height": 420, "fill": "rgba(10,5,5,0.75)", "panelBorderWidth": 1, "panelBorderColor": "#c5b358", "panelRadius": 0}, {"id": "da_0040", "type": "text", "zIndex": 3, "x": 52, "y": 320, "width": 424, "height": 380, "content": "The fire crackles in ways fire shouldn't. The sparks drift upward and they don't so much disappear as keep going ever higher, climbing into a sky that has far too many stars and not enough familiar constellations.\n\nThe moon is the wrong color — copper, tinged by forest-fire trails — hanging low and fat like a drunk uncle at a wedding grinning too much and not saying anything except \"yup.\"\n\nZen doesn't care. Zen has never cared about the astronomical implications of anything. She's curled on my lap, a long-haired tuxedo with a bikini patch of white fur draped across her belly. She purrs. It soothes my nerves more than she will ever truly know.\n\nShe goes everywhere with me. Even when where is some place like here.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#e8e4d9", "align": "left", "lineHeight": 1.4}], "bgm": "gen:nature"}, {"id": 1000000000047, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0041", "type": "image", "zIndex": 0, "x": -60, "y": 500, "width": 240, "height": 240, "src": "/assets/devils-atlas/ink-splat18.png", "objectFit": "cover", "opacity": 0.4, "rotation": -30}, {"id": "da_0042", "type": "text", "zIndex": 2, "x": 40, "y": 36, "width": 448, "height": 36, "content": "ZEN", "fontFamily": "Special Elite", "fontSize": 36, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0043", "type": "text", "zIndex": 2, "x": 40, "y": 76, "width": 448, "height": 24, "content": "The main cat on this journey", "fontFamily": "Special Elite", "fontSize": 13, "color": "#666", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0044", "type": "text", "zIndex": 2, "x": 40, "y": 110, "width": 448, "height": 420, "content": "Zen is a tuxedo rescue who jumped up and greeted me as soon as I entered the room at the shelter. She immediately demanded I turn on the tap and feed her fresh running water. She licked my hand and rubbed her head against me telling me I was hired.\n\nFor nine years we have been inseparable. I rail against many things in the world, but not Zen. She has never doubted the nature of reality like I have. She has never worried about rent or gluten or whether her manager thinks she's a \"cultural fit.\"\n\nAll that matters to her is in the moment. Her food bowl should be full. The lap should be warm. Water should be fresh. The purr is in the moment and in that moment, all is good.\n\nI should have learned from her earlier.\n\nInstead, I had to lose everything first.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0045", "type": "balloon", "zIndex": 3, "x": 300, "y": 540, "width": 180, "height": 70, "content": "are you done yet?", "balloonType": "thought", "fontSize": 12, "fontFamily": "Comic Neue", "animation": "flash-in", "animDuration": 1}, {"id": "da_0046", "type": "panel", "zIndex": 2, "x": 40, "y": 640, "width": 448, "height": 100, "fill": "#1a1a1a", "panelBorderWidth": 0, "panelBorderColor": "#1a1a1a", "panelRadius": 0}, {"id": "da_0047", "type": "text", "zIndex": 3, "x": 50, "y": 655, "width": 428, "height": 70, "content": "The world is a lie. The maps are wrong.\nIf you find a seam — keep driving.", "fontFamily": "Special Elite", "fontSize": 14, "color": "#c5b358", "align": "center", "lineHeight": 1.35}]}, {"id": 1000000000051, "background": "#0d0d0d", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0048", "type": "image", "zIndex": 0, "x": 200, "y": 100, "width": 300, "height": 300, "src": "/assets/devils-atlas/blood-splat12.png", "objectFit": "cover", "opacity": 0.5, "rotation": 10, "blendMode": "screen"}, {"id": "da_0049", "type": "text", "zIndex": 2, "x": 234, "y": 60, "width": 60, "height": 50, "content": "☠", "fontSize": 40, "align": "center", "color": "#4a0000"}, {"id": "da_0050", "type": "text", "zIndex": 2, "x": 40, "y": 120, "width": 448, "height": 36, "content": "THE SPOILER", "fontFamily": "Special Elite", "fontSize": 26, "color": "#c5b358", "align": "center", "bold": true}, {"id": "da_0051", "type": "text", "zIndex": 2, "x": 40, "y": 180, "width": 448, "height": 520, "content": "If you want to stop here and not read the rest — let me save you some time.\n\nThe world is a lie. The maps are wrong. Your landlord is a parasite, your boss is a prison guard, and the GPS on your phone is a tool of mass deception designed by an organization that treats human civilization like a particularly profitable ant farm.\n\nHuman Resources is an anti-human pathological sex-machine embodied through savage penance and punitive policy — swung as one swings a BDSM whip in a CIA black room.\n\nAnd somewhere out there, just past the edges of the map you were handed in grade school, there are seams. Cracks in the lie. And possibly, a road that shouldn't exist.\n\nIf you find one, keep driving.\n\nZen just yawned. She's hungry. She's always hungry.\n\nThe world can wait. The cat cannot.", "fontFamily": "Courier Prime", "fontSize": 13, "color": "#ddd", "align": "left", "lineHeight": 1.4}]}, {"id": 1000000000058, "background": "#4a0000", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0052", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "smoke", "opacity": 0.4}, {"id": "da_0053", "type": "image", "zIndex": 1, "x": -80, "y": -80, "width": 400, "height": 400, "src": "/assets/devils-atlas/blood-splat22.png", "objectFit": "cover", "opacity": 0.6, "blendMode": "screen"}, {"id": "da_0054", "type": "image", "zIndex": 1, "x": 250, "y": 450, "width": 350, "height": 350, "src": "/assets/devils-atlas/blood-splat00.png", "objectFit": "cover", "opacity": 0.5, "blendMode": "screen", "rotation": -20}, {"id": "da_0055", "type": "text", "zIndex": 3, "x": 40, "y": 280, "width": 448, "height": 30, "content": "PART ONE", "fontFamily": "Courier Prime", "fontSize": 14, "color": "#c5b358", "align": "center", "lineHeight": 1.35, "letterSpacing": 8}, {"id": "da_0056", "type": "text", "zIndex": 3, "x": 40, "y": 330, "width": 448, "height": 60, "content": "THE SLIDE", "fontFamily": "Cinzel", "fontSize": 56, "color": "#e8e4d9", "align": "center", "bold": true, "textShadow": "6px 6px 0 #000"}, {"id": "da_0057", "type": "text", "zIndex": 3, "x": 40, "y": 420, "width": 448, "height": 30, "content": "Fired. Bluffed. Evicted. Gone.", "fontFamily": "Special Elite", "fontSize": 16, "color": "#c5b358", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0058", "type": "text", "zIndex": 4, "x": 164, "y": 560, "width": 200, "height": 40, "content": "CHAPTER 1 →", "action": "goto", "actionVal": "8", "fontFamily": "Special Elite", "fontSize": 14, "color": "#000", "align": "center", "bold": true, "fill": "#c5b358", "borderRadius": 4}], "bgm": "gen:drone"}, {"id": 1000000000071, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0059", "type": "text", "zIndex": 2, "x": 40, "y": 24, "width": 448, "height": 20, "content": "CHAPTER 1", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#4a0000", "align": "left", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0060", "type": "text", "zIndex": 2, "x": 40, "y": 48, "width": 448, "height": 36, "content": "The Unceremonious Firing", "fontFamily": "Special Elite", "fontSize": 22, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0061", "type": "text", "zIndex": 2, "x": 40, "y": 88, "width": 448, "height": 40, "content": "Or, How I Learned That \"Cultural Misalignment\" Means \"You Were Too Good\"", "fontFamily": "EB Garamond", "fontSize": 12, "color": "#666", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0062", "type": "panel", "zIndex": 1, "x": 40, "y": 140, "width": 210, "height": 130, "fill": "#1a1a2e", "panelBorderWidth": 3, "panelBorderColor": "#333", "panelRadius": 0}, {"id": "da_0063", "type": "panel", "zIndex": 1, "x": 278, "y": 140, "width": 210, "height": 130, "fill": "#1a1a2e", "panelBorderWidth": 3, "panelBorderColor": "#333", "panelRadius": 0}, {"id": "da_0064", "type": "text", "zIndex": 2, "x": 40, "y": 150, "width": 210, "height": 20, "content": "BLAKE", "fontFamily": "Orbitron", "fontSize": 10, "color": "#00f3ff", "align": "center", "lineHeight": 1.35}, {"id": "da_0065", "type": "text", "zIndex": 2, "x": 50, "y": 200, "width": 190, "height": 40, "content": "(benign managerial concern)", "fontFamily": "Roboto Mono", "fontSize": 10, "color": "#888", "align": "center", "lineHeight": 1.35}, {"id": "da_0066", "type": "text", "zIndex": 2, "x": 278, "y": 150, "width": 210, "height": 20, "content": "LYSE — HR", "fontFamily": "Orbitron", "fontSize": 10, "color": "#ff003c", "align": "center", "lineHeight": 1.35}, {"id": "da_0067", "type": "text", "zIndex": 2, "x": 288, "y": 200, "width": 190, "height": 40, "content": "empathy slider: 0", "fontFamily": "Roboto Mono", "fontSize": 10, "color": "#888", "align": "center", "lineHeight": 1.35}, {"id": "da_0068", "type": "balloon", "zIndex": 3, "x": 40, "y": 290, "width": 210, "height": 70, "content": "That's very... ambitious, John.", "balloonType": "dialog", "fontSize": 11, "fontFamily": "Comic Neue"}, {"id": "da_0069", "type": "balloon", "zIndex": 3, "x": 278, "y": 290, "width": 210, "height": 70, "content": "John, I think we need to discuss something else.", "balloonType": "caption", "fontSize": 11, "fontFamily": "Comic Neue"}, {"id": "da_0070", "type": "text", "zIndex": 2, "x": 40, "y": 380, "width": 448, "height": 280, "content": "Three cups of coffee. A Zyn under the lip like a prayer. Project Tectonic on screen — my beautiful, doomed Project Tectonic. It would save the company $2.3 million annually. It would make the team happier.\n\nI presented it with the confidence of a man who has done the math and knows the math is sound.\n\nSilence. The kind that isn't empty but full — full of things being decided without you.\n\nAnd then she fired me.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0071", "type": "text", "zIndex": 4, "x": 164, "y": 700, "width": 200, "height": 40, "content": "CAST FLASH", "action": "vfx", "actionVal": "flash", "fontFamily": "Orbitron", "fontSize": 14, "color": "#fff", "align": "center", "bold": true, "fill": "#ff003c", "borderRadius": 4}]}, {"id": 1000000000076, "background": "#110808", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0072", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "lightning", "opacity": 0.25}, {"id": "da_0073", "type": "text", "zIndex": 3, "x": 60, "y": 60, "width": 400, "height": 70, "content": "FIRED!", "fontFamily": "Bangers", "fontSize": 64, "color": "#ff003c", "align": "center", "bold": true, "strokeWidth": 2, "strokeColor": "#000", "rotation": -6, "animation": "shake", "animDuration": 0.5, "animLoop": true}, {"id": "da_0074", "type": "text", "zIndex": 2, "x": 40, "y": 160, "width": 448, "height": 36, "content": "\"Cultural misalignment\"", "fontFamily": "Special Elite", "fontSize": 20, "color": "#c5b358", "align": "center", "lineHeight": 1.35}, {"id": "da_0075", "type": "text", "zIndex": 2, "x": 40, "y": 220, "width": 448, "height": 420, "content": "That's what you say when someone is too good at their job and makes everyone else look bad. That's what you say when you need to punish competence because competence threatens the hierarchy.\n\n\"Failure to exhibit team cohesion,\" Blake added, reading from a script. His eyes kept darting down and to the left. He'd practiced this.\n\n\"Your computer access has been terminated. Your personal effects will be mailed to you. We've met our legal obligations.\"\n\nThe Zoom window disappeared.\n\nI screamed at the blank screen. Long enough that my throat went raw and Zen looked up from the couch with an expression that said are you done yet?\n\nThen the email — timestamped during my screaming fit. She had pre-written it for my emotional breakdown.\n\n\"We have met the bare legal minimum.\"\n\nFour words that should be carved on the tombstone of late capitalism.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#ddd", "align": "left", "lineHeight": 1.4}, {"id": "da_0076", "type": "text", "zIndex": 4, "x": 144, "y": 680, "width": 240, "height": 40, "content": "SHAKE THE ROOM", "action": "vfx", "actionVal": "shake", "fontFamily": "Special Elite", "fontSize": 14, "color": "#000", "align": "center", "bold": true, "fill": "#c5b358", "borderRadius": 4}]}, {"id": 1000000000081, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0077", "type": "panel", "zIndex": 0, "x": 30, "y": 30, "width": 468, "height": 756, "fill": "#f5f0e6", "panelBorderWidth": 3, "panelBorderColor": "#1a1a1a", "panelRadius": 0, "panelBorderStyle": "dashed"}, {"id": "da_0078", "type": "text", "zIndex": 2, "x": 50, "y": 50, "width": 428, "height": 24, "content": "GONZO DIGRESSION #1", "fontFamily": "Bangers", "fontSize": 18, "color": "#e44", "align": "center", "lineHeight": 1.35}, {"id": "da_0079", "type": "text", "zIndex": 2, "x": 50, "y": 85, "width": 428, "height": 50, "content": "On the Smell of Corporate Air", "fontFamily": "Special Elite", "fontSize": 20, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0080", "type": "text", "zIndex": 2, "x": 50, "y": 150, "width": 428, "height": 500, "content": "Have you ever noticed that office buildings all smell the same? It's not natural. Some HVAC technician in a windowless room designed that smell — recycled air filtered through cheap filters, laced with industrial carpet cleaner and the collective anxiety of everyone who's ever cried in a bathroom stall between meetings.\n\nThat smell was in my apartment now. Metaphorically. The smell of being managed. Of being assessed. Of being found wanting by people whose only skill is finding others wanting.\n\nZen jumped onto my chest and purred — the cat equivalent of a defibrillator.\n\n\"They fired me,\" I told her.\nShe blinked.\n\"I was too good at my job.\"\nShe yawned.\n\"I'm going to be homeless in thirty days.\"\nShe tucked her paws under her chest and closed her eyes.\n\"Thank you for your support,\" I said. \"It means the world to me.\"\nHer tail flicked.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0081", "type": "balloon", "zIndex": 3, "x": 160, "y": 660, "width": 200, "height": 60, "content": "I told you so.", "balloonType": "whisper", "fontSize": 12, "fontFamily": "Comic Neue"}]}, {"id": 1000000000089, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0082", "type": "text", "zIndex": 2, "x": 40, "y": 24, "width": 448, "height": 20, "content": "CHAPTER 2", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#4a0000", "align": "left", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0083", "type": "text", "zIndex": 2, "x": 40, "y": 48, "width": 448, "height": 36, "content": "The Unhiring", "fontFamily": "Special Elite", "fontSize": 24, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0084", "type": "text", "zIndex": 2, "x": 40, "y": 90, "width": 448, "height": 36, "content": "Or, How I Bluffed for Sixteen Weeks and Won a War I Didn't Want", "fontFamily": "EB Garamond", "fontSize": 12, "color": "#666", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0085", "type": "text", "zIndex": 2, "x": 40, "y": 140, "width": 448, "height": 340, "content": "The severance negotiation lasted a month. Emails. Legal threats. Waking at 3 AM with my heart pounding and Zen sitting on my chest like a furry little EMT.\n\nI had no lawyer, no case, no leverage — only righteous indignation and a complete inability to let things go. I wrote Lyse three thousand words. She responded in four sentences.\n\nI escalated. I named lawyers I had not yet called. The email chain grew longer than the Circuit de la Sarthe — a Le Mans of correspondence.\n\nWeek three: I claimed I had retained counsel. I hadn't. I'd posted on a legal advice subreddit.\n\nWeek four: she caved.\n\nSixteen weeks of severance.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0086", "type": "panel", "zIndex": 1, "x": 40, "y": 500, "width": 448, "height": 120, "fill": "#1a1a1a", "panelBorderWidth": 2, "panelBorderColor": "#c5b358", "panelRadius": 0}, {"id": "da_0087", "type": "text", "zIndex": 2, "x": 40, "y": 520, "width": 448, "height": 40, "content": "十六 WEEKS", "fontFamily": "Bebas Neue", "fontSize": 36, "color": "#c5b358", "align": "center", "lineHeight": 1.35}, {"id": "da_0088", "type": "text", "zIndex": 2, "x": 40, "y": 570, "width": 448, "height": 30, "content": "\"Don't celebrate yet.\" — Zen, probably", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#888", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0089", "type": "text", "zIndex": 3, "x": 114, "y": 660, "width": 300, "height": 40, "content": "REVEAL THE SPECIES LYSE →", "action": "goto", "actionVal": "12", "fontFamily": "Special Elite", "fontSize": 14, "color": "#000", "align": "center", "bold": true, "fill": "#c5b358", "borderRadius": 4}]}, {"id": 1000000000095, "background": "#000000", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0090", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "voidNoise", "opacity": 0.35}, {"id": "da_0091", "type": "text", "zIndex": 2, "x": 234, "y": 40, "width": 60, "height": 50, "content": "☢", "fontSize": 40, "align": "center", "color": "#00ff00", "animation": "pulse", "animDuration": 1.5, "animLoop": true}, {"id": "da_0092", "type": "text", "zIndex": 2, "x": 40, "y": 100, "width": 448, "height": 24, "content": "GONZO DIGRESSION #2", "fontFamily": "Bangers", "fontSize": 18, "color": "#00ff00", "align": "center", "lineHeight": 1.35}, {"id": "da_0093", "type": "text", "zIndex": 2, "x": 40, "y": 135, "width": 448, "height": 40, "content": "On the Species Lyse", "fontFamily": "Special Elite", "fontSize": 24, "color": "#c5b358", "align": "center", "bold": true}, {"id": "da_0094", "type": "text", "zIndex": 2, "x": 40, "y": 200, "width": 448, "height": 440, "content": "There is a species of human that thrives in HR departments. They are not born — they are assembled. Somewhere in the basement of every major corporation, a machine strips out empathy, humor, and the ability to recognize when you are destroying someone's life for no reason other than policy.\n\nWhen it's done, it produces someone like Lyse — a person who can fire a hundred people before lunch and then eat a salad while discussing engagement metrics.\n\nShe wasn't evil. Evil requires passion. Evil requires investment.\n\nLyse was something worse.\n\nShe was efficient.\n\nI hope she's reading this. I hope she feels nothing at all. Because that's the worst punishment I can imagine for someone like her: to see the truth and be unable to care about it.", "fontFamily": "Courier Prime", "fontSize": 13, "color": "#cfc", "align": "left", "lineHeight": 1.4}, {"id": "da_0095", "type": "text", "zIndex": 2, "x": 40, "y": 680, "width": 448, "height": 30, "content": "[ EFFICIENCY ≠ HUMANITY ]", "fontFamily": "Orbitron", "fontSize": 12, "color": "#00ff00", "align": "center", "lineHeight": 1.35, "letterSpacing": 2}]}, {"id": 1000000000101, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0096", "type": "text", "zIndex": 2, "x": 40, "y": 24, "width": 448, "height": 20, "content": "CHAPTER 3", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#4a0000", "align": "left", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0097", "type": "text", "zIndex": 2, "x": 40, "y": 48, "width": 448, "height": 36, "content": "The Moveout Demisaster", "fontFamily": "Special Elite", "fontSize": 22, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0098", "type": "text", "zIndex": 2, "x": 40, "y": 90, "width": 448, "height": 36, "content": "Or, How I Learned to Hate Landlords and Everything They Stand For", "fontFamily": "EB Garamond", "fontSize": 12, "color": "#666", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0099", "type": "text", "zIndex": 2, "x": 40, "y": 140, "width": 448, "height": 460, "content": "Margaret Geller owned seventeen properties across the GTA. She had never set foot in any of them. She was a spreadsheet in human form.\n\nFifteen percent rent increase. Proof of income. And — this is the part that made me laugh into an asthma attack — $2,100 in \"damages.\" Each photograph a lie. Normal wear sold as vandalism.\n\nTwo days later, the man showed up. Built like an old refrigerator. Eyes the color of wet pavement.\n\n\"Margaret Geller sent me. She wanted me to remind you that the damages need to be paid. And that the lease expires on Friday.\"\n\n\"Aggressive measures,\" he said, without saying what that meant.\n\nI didn't sleep that night. By dawn the apartment was empty. Just walls. Just ghosts.\n\nI picked up Zen's carrier. She meowed in protest.\n\"I don't know where we're going. But we're going.\"\nI didn't look back.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0100", "type": "text", "zIndex": 3, "x": 160, "y": 620, "width": 200, "height": 50, "content": "GONE", "fontFamily": "Bangers", "fontSize": 36, "color": "#4a0000", "align": "center", "bold": true, "strokeWidth": 2, "strokeColor": "#000", "rotation": 0, "animation": "flash-in", "animDuration": 1}, {"id": "da_0101", "type": "text", "zIndex": 3, "x": 164, "y": 700, "width": 200, "height": 40, "content": "HIT THE ROAD →", "action": "goto", "actionVal": "14", "fontFamily": "Special Elite", "fontSize": 14, "color": "#000", "align": "center", "bold": true, "fill": "#c5b358", "borderRadius": 4}]}, {"id": 1000000000107, "background": "#2a2a2a", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0102", "type": "image", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 300, "src": "/assets/devils-atlas/road-cabin.jpg", "objectFit": "cover", "opacity": 0.7}, {"id": "da_0103", "type": "panel", "zIndex": 1, "x": 0, "y": 240, "width": 528, "height": 80, "fill": "transparent", "panelBorderWidth": 2, "panelBorderColor": "#1a1a1a", "panelRadius": 0}, {"id": "da_0104", "type": "panel", "zIndex": 1, "x": 0, "y": 220, "width": 528, "height": 100, "fill": "rgba(42,42,42,0.9)", "panelBorderWidth": 0, "panelBorderColor": "#1a1a1a", "panelRadius": 0}, {"id": "da_0105", "type": "text", "zIndex": 3, "x": 40, "y": 40, "width": 448, "height": 20, "content": "CHAPTER 4", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#c5b358", "align": "left", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0106", "type": "text", "zIndex": 3, "x": 40, "y": 70, "width": 448, "height": 80, "content": "THE LONG\nGREY ROAD", "fontFamily": "Cinzel", "fontSize": 32, "color": "#e8e4d9", "align": "center", "bold": true, "textShadow": "3px 3px 0 #000"}, {"id": "da_0107", "type": "text", "zIndex": 2, "x": 40, "y": 320, "width": 448, "height": 380, "content": "The Trans-Canada Highway is the longest national highway in the world. It is also, with all the love in my heart, a monument to human misery.\n\n$4,200 left. Gas, rice cakes, hard-boiled eggs, Zyn. Ninety days before irreversible broke.\n\nThe car became my home — a 2012 Hyundai Elantra, silver, check-engine light on so long I'd stopped noticing. Zen claimed the passenger seat. Cats are remarkably adaptable.\n\nTruck-stop showers: $12 for three minutes of hot water and the illusion you are still a person.\n\nCeliac + gas station food = a diet that would make a nutritionist weep. Asthma + forest fire smoke = Ventolin rationed like wartime morphine.\n\n\"You're not going to die,\" I told myself, wheezing. \"You're just going to feel like you're dying for a while.\"", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#ddd", "align": "left", "lineHeight": 1.4}], "bgm": "gen:drone"}, {"id": 1000000000114, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0108", "type": "text", "zIndex": 2, "x": 40, "y": 30, "width": 448, "height": 36, "content": "CATASTROPHES, IN WAVES", "fontFamily": "Special Elite", "fontSize": 20, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0109", "type": "text", "zIndex": 3, "x": 20, "y": 80, "width": 160, "height": 50, "content": "CRASH!", "fontFamily": "Bangers", "fontSize": 32, "color": "#e44", "align": "center", "bold": true, "strokeWidth": 2, "strokeColor": "#000", "rotation": -12, "animation": "shake", "animDuration": 0.6}, {"id": "da_0110", "type": "text", "zIndex": 3, "x": 180, "y": 90, "width": 160, "height": 50, "content": "WHOOSH", "fontFamily": "Bangers", "fontSize": 28, "color": "#4af", "align": "center", "bold": true, "strokeWidth": 2, "strokeColor": "#000", "rotation": 8, "animation": "shake", "animDuration": 0.6}, {"id": "da_0111", "type": "text", "zIndex": 3, "x": 340, "y": 80, "width": 160, "height": 50, "content": "SMASH!", "fontFamily": "Bangers", "fontSize": 32, "color": "#f80", "align": "center", "bold": true, "strokeWidth": 2, "strokeColor": "#000", "rotation": -5, "animation": "shake", "animDuration": 0.6}, {"id": "da_0112", "type": "text", "zIndex": 2, "x": 40, "y": 150, "width": 448, "height": 420, "content": "Bombing range: GPS led me to \"WARNING: LIVE ORDNANCE.\" Logging truck: missed by six inches. Thunder Bay: smashed window, stolen sleeping bag, stolen stove. They left the rice cakes — somehow more insulting.\n\nAn old man appeared with duct tape and plastic.\n\"We're all just trying to get somewhere. No sense making it harder on each other.\"\n\nThe Rockies. A cliff. A long way down. One step and it would all be over.\n\nZen meowed from the hood of the car.\nDon't you fucking dare.\n\n\"I wasn't going to,\" I said. \"I was just... looking.\"\n\nThe small kindnesses kept me alive. Gluten-free bannock in Saskatchewan. A shared campfire in Alberta. A bag of apples from a stranger.\n\nThose people saved my life. Not metaphorically. Literally.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0113", "type": "balloon", "zIndex": 3, "x": 140, "y": 600, "width": 240, "height": 70, "content": "Don't you fucking dare.", "balloonType": "shout", "fontSize": 13, "fontFamily": "Comic Neue", "animation": "shake", "animDuration": 0.8}, {"id": "da_0114", "type": "text", "zIndex": 3, "x": 144, "y": 700, "width": 240, "height": 40, "content": "CROSS THE SEAM →", "action": "goto", "actionVal": "16", "fontFamily": "Special Elite", "fontSize": 14, "color": "#c5b358", "align": "center", "bold": true, "fill": "#4a0000", "borderRadius": 4}]}, {"id": 1000000000120, "background": "#0a1628", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0115", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "galaxy", "opacity": 0.5}, {"id": "da_0116", "type": "image", "zIndex": 1, "x": 0, "y": 400, "width": 528, "height": 416, "src": "/assets/devils-atlas/sky-wrong.jpg", "objectFit": "cover", "opacity": 0.4, "blendMode": "overlay"}, {"id": "da_0117", "type": "text", "zIndex": 3, "x": 40, "y": 280, "width": 448, "height": 30, "content": "PART TWO", "fontFamily": "Courier Prime", "fontSize": 14, "color": "#00f3ff", "align": "center", "lineHeight": 1.35, "letterSpacing": 8}, {"id": "da_0118", "type": "text", "zIndex": 3, "x": 40, "y": 330, "width": 448, "height": 60, "content": "THE SEAM", "fontFamily": "Cinzel", "fontSize": 56, "color": "#e8e4d9", "align": "center", "bold": true, "textShadow": "0 0 20px #00f3ff"}, {"id": "da_0119", "type": "text", "zIndex": 3, "x": 40, "y": 420, "width": 448, "height": 30, "content": "Ninety minutes from the Rockies to Mongolia.", "fontFamily": "Special Elite", "fontSize": 14, "color": "#00f3ff", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0120", "type": "text", "zIndex": 4, "x": 164, "y": 560, "width": 200, "height": 40, "content": "ARRIVE →", "action": "goto", "actionVal": "17", "fontFamily": "Special Elite", "fontSize": 14, "color": "#000", "align": "center", "bold": true, "fill": "#00f3ff", "borderRadius": 4}], "bgm": "gen:cyber"}, {"id": 1000000000124, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0121", "type": "text", "zIndex": 2, "x": 40, "y": 24, "width": 448, "height": 20, "content": "CHAPTER 5", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#4a0000", "align": "left", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0122", "type": "text", "zIndex": 2, "x": 40, "y": 48, "width": 448, "height": 50, "content": "Welcome to the Neighbourhood", "fontFamily": "Special Elite", "fontSize": 20, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0123", "type": "text", "zIndex": 2, "x": 40, "y": 110, "width": 448, "height": 500, "content": "I don't know exactly when I crossed the seam. The GPS recalculated every thirty seconds. The road was narrow and unpaved and shouldn't have been there at all. The sky was the wrong color. The sun was in the wrong position.\n\nI drove for ninety minutes. Maybe less. Time got strange. The dashboard said 2:47 PM and then 4:23 AM and then nothing at all — just a blinking 12:00.\n\nAnd then the road ended, and I was in Mongolia.\n\nChildren saw my car first — Ontario plates, garbage-bag window, hollow-eyed face. One boy grabbed my phone, typed into Google Translate, and handed it back:\n\n\"Poor stupid foreigner.\"\n\nI laughed. First time in weeks. It hurt. It triggered a coughing fit. Fair enough.\n\nAn old woman fed me yogurt and mutton. I tried to explain celiac. She said something that meant \"stop being picky and eat.\" It was the best meal of my life.\n\nI paid with a Loonie. She laughed and tucked it in her pocket.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0124", "type": "balloon", "zIndex": 3, "x": 140, "y": 640, "width": 240, "height": 60, "content": "Poor stupid foreigner.", "balloonType": "dialog", "fontSize": 13, "fontFamily": "Comic Neue"}]}, {"id": 1000000000130, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0125", "type": "image", "zIndex": 0, "x": 300, "y": -50, "width": 280, "height": 280, "src": "/assets/devils-atlas/ink-splat27.png", "objectFit": "cover", "opacity": 0.3, "rotation": 15}, {"id": "da_0126", "type": "text", "zIndex": 2, "x": 40, "y": 40, "width": 448, "height": 40, "content": "KARMA", "fontFamily": "Special Elite", "fontSize": 36, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0127", "type": "text", "zIndex": 2, "x": 40, "y": 90, "width": 448, "height": 24, "content": "Nergüi's granddaughter — waiting nine years", "fontFamily": "Special Elite", "fontSize": 13, "color": "#666", "align": "center", "lineHeight": 1.35, "italic": true}, {"id": "da_0128", "type": "balloon", "zIndex": 3, "x": 40, "y": 130, "width": 448, "height": 90, "content": "You're not crazy. You're not having a breakdown. You're exactly where you're supposed to be.", "balloonType": "dialog", "fontSize": 13, "fontFamily": "Comic Neue"}, {"id": "da_0129", "type": "text", "zIndex": 2, "x": 40, "y": 250, "width": 448, "height": 380, "content": "She arrived as I was eating breakfast. Sharp features. Sharper eyes. The look of someone disappointed by the universe so many times she no longer expected anything else.\n\n\"Because the same thing happened to me nine years ago. I found a seam. I crossed through. I was gone for two days and came back with a story no one believed. I've been the town joke ever since.\"\n\n\"I've been looking for someone like you for a very long time. Someone who would prove I wasn't crazy.\"\n\n\"The world is a lie. The maps are wrong. And your cat knows more about it than you do.\"\n\nI looked at Zen. Zen looked at me.\n\n\"Well,\" I said. \"That explains a lot, actually.\"", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0130", "type": "balloon", "zIndex": 3, "x": 280, "y": 660, "width": 200, "height": 60, "content": "I'll take that as a yes.", "balloonType": "thought", "fontSize": 12, "fontFamily": "Comic Neue"}]}, {"id": 1000000000148, "background": "#0a0a0a", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0131", "type": "text", "zIndex": 2, "x": 40, "y": 24, "width": 448, "height": 20, "content": "CHAPTER 6", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#00ff00", "align": "left", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0132", "type": "text", "zIndex": 2, "x": 40, "y": 50, "width": 448, "height": 36, "content": "The Geography of Lies", "fontFamily": "Special Elite", "fontSize": 22, "color": "#c5b358", "align": "center", "bold": true}, {"id": "da_0133", "type": "panel", "zIndex": 1, "x": 64, "y": 110, "width": 90, "height": 70, "fill": "#1a3a1a", "panelBorderWidth": 1, "panelBorderColor": "#00ff00", "panelRadius": 0}, {"id": "da_0134", "type": "panel", "zIndex": 1, "x": 164, "y": 110, "width": 90, "height": 70, "fill": "#1a1a3a", "panelBorderWidth": 1, "panelBorderColor": "#00ff00", "panelRadius": 0}, {"id": "da_0135", "type": "panel", "zIndex": 1, "x": 264, "y": 110, "width": 90, "height": 70, "fill": "#3a1a1a", "panelBorderWidth": 1, "panelBorderColor": "#00ff00", "panelRadius": 0}, {"id": "da_0136", "type": "panel", "zIndex": 1, "x": 364, "y": 110, "width": 90, "height": 70, "fill": "#3a3a1a", "panelBorderWidth": 1, "panelBorderColor": "#00ff00", "panelRadius": 0}, {"id": "da_0137", "type": "panel", "zIndex": 1, "x": 64, "y": 190, "width": 90, "height": 70, "fill": "#1a3a3a", "panelBorderWidth": 1, "panelBorderColor": "#00ff00", "panelRadius": 0}, {"id": "da_0138", "type": "panel", "zIndex": 1, "x": 164, "y": 190, "width": 90, "height": 70, "fill": "#3a1a3a", "panelBorderWidth": 2, "panelBorderColor": "#c5b358", "panelRadius": 0}, {"id": "da_0139", "type": "panel", "zIndex": 1, "x": 264, "y": 190, "width": 90, "height": 70, "fill": "#2a2a2a", "panelBorderWidth": 1, "panelBorderColor": "#00ff00", "panelRadius": 0}, {"id": "da_0140", "type": "panel", "zIndex": 1, "x": 364, "y": 190, "width": 90, "height": 70, "fill": "#1a2a3a", "panelBorderWidth": 1, "panelBorderColor": "#00ff00", "panelRadius": 0}, {"id": "da_0141", "type": "text", "zIndex": 2, "x": 64, "y": 130, "width": 90, "height": 20, "content": "CAN", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#0f0", "align": "center", "lineHeight": 1.35}, {"id": "da_0142", "type": "text", "zIndex": 2, "x": 164, "y": 130, "width": 90, "height": 20, "content": "MNG", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#0f0", "align": "center", "lineHeight": 1.35}, {"id": "da_0143", "type": "text", "zIndex": 2, "x": 264, "y": 130, "width": 90, "height": 20, "content": "USA", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#0f0", "align": "center", "lineHeight": 1.35}, {"id": "da_0144", "type": "text", "zIndex": 2, "x": 364, "y": 130, "width": 90, "height": 20, "content": "CHN", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#0f0", "align": "center", "lineHeight": 1.35}, {"id": "da_0145", "type": "text", "zIndex": 2, "x": 164, "y": 200, "width": 90, "height": 50, "content": "YOU\nARE\nHERE", "fontFamily": "Courier Prime", "fontSize": 9, "color": "#c5b358", "align": "center", "lineHeight": 1.35}, {"id": "da_0146", "type": "text", "zIndex": 2, "x": 40, "y": 290, "width": 448, "height": 380, "content": "The Earth is a plane. Not a sphere. A vast flat expanse. The globe is a projection — a surface designed to make us think we're on a ball.\n\nThe Greater Earth Organization. The GEO. Governments are figureheads. The GEO runs the show.\n\nCanada beside Mongolia. Korea next to Portland. Australia next to Texas.\n\n\"Your anxiety. Your paranoia. Your body's constant screaming that something is wrong — that's not a disorder, John. That's a detection system.\"\n\nI laughed until I coughed. Reached for Ventolin. Kept laughing.\n\n\"I was right the whole time?\"\n\"Yes.\"", "fontFamily": "Courier Prime", "fontSize": 13, "color": "#cfc", "align": "left", "lineHeight": 1.4}, {"id": "da_0147", "type": "text", "zIndex": 4, "x": 114, "y": 700, "width": 300, "height": 40, "content": "REVEAL CLASSIFIED MAP", "action": "toggle", "actionVal": "geo-map", "fontFamily": "Orbitron", "fontSize": 12, "color": "#000", "align": "center", "bold": true, "fill": "#00ff00", "borderRadius": 4}, {"id": "da_0148", "type": "image", "zIndex": 5, "x": 64, "y": 480, "width": 400, "height": 200, "src": "/assets/devils-atlas/world-map.jpg", "objectFit": "cover", "opacity": 0.85, "isHidden": true, "label": "geo-map", "filter": "grayscale(0.4) contrast(1.2)", "blendMode": "screen"}], "bgm": "gen:horror"}, {"id": 1000000000154, "background": "#e8e4d9", "texture": "https://www.transparenttextures.com/patterns/old-mathematics.png", "elements": [{"id": "da_0149", "type": "text", "zIndex": 2, "x": 40, "y": 24, "width": 448, "height": 20, "content": "CHAPTER 7", "fontFamily": "Courier Prime", "fontSize": 10, "color": "#4a0000", "align": "left", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0150", "type": "text", "zIndex": 2, "x": 40, "y": 48, "width": 448, "height": 40, "content": "The Devil's Atlas", "fontFamily": "Special Elite", "fontSize": 26, "color": "#4a0000", "align": "center", "bold": true}, {"id": "da_0151", "type": "text", "zIndex": 2, "x": 234, "y": 100, "width": 60, "height": 50, "content": "🧭", "fontSize": 40, "align": "center", "color": "#c5b358", "animation": "spin", "animDuration": 8, "animLoop": true}, {"id": "da_0152", "type": "text", "zIndex": 2, "x": 40, "y": 170, "width": 448, "height": 420, "content": "Ganbaatar the mapkeeper lived at the edge of the market. Maps covered every surface — ancient and yellowed, none looking like any map I'd ever seen.\n\n\"This is the Devil's Atlas. The true projection. The real map of the world.\"\n\nA plane. Divided into a grid. Seams visible — thin cracks between territories.\n\n\"Maps have always been political weapons. Control the map, control the world. GPS is the ultimate tool of the Geographers. It guides us through a fake reality.\"\n\nHe gave me a brass compass. The needle didn't point north. It pointed to the Boundary — the heart of the lie.\n\n\"I've been keeping these maps for sixty years. I was starting to think I'd die before anyone came for them.\"\n\n\"Okay,\" I said. \"Let's find the Boundary. Let's break through.\"", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#222", "align": "left", "lineHeight": 1.4}, {"id": "da_0153", "type": "text", "zIndex": 3, "x": 114, "y": 640, "width": 300, "height": 40, "content": "ENTER CLASSIFIED PAGE 🔒", "action": "password", "actionVal": "21", "fontFamily": "Special Elite", "fontSize": 14, "color": "#c5b358", "align": "center", "bold": true, "fill": "#1a1a1a", "borderRadius": 4}, {"id": "da_0154", "type": "text", "zIndex": 2, "x": 40, "y": 700, "width": 448, "height": 24, "content": "password hint: the crack in the lie", "fontFamily": "Courier Prime", "fontSize": 11, "color": "#888", "align": "center", "lineHeight": 1.35, "italic": true}]}, {"id": 1000000000160, "background": "#050505", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0155", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "energy", "opacity": 0.4}, {"id": "da_0156", "type": "text", "zIndex": 2, "x": 234, "y": 60, "width": 60, "height": 50, "content": "⛤", "fontSize": 40, "align": "center", "color": "#bc00ff", "animation": "pulse", "animDuration": 2, "animLoop": true}, {"id": "da_0157", "type": "text", "zIndex": 2, "x": 40, "y": 130, "width": 448, "height": 24, "content": "// CLASSIFIED — THREAD EYES ONLY", "fontFamily": "Courier Prime", "fontSize": 11, "color": "#bc00ff", "align": "center", "lineHeight": 1.35, "letterSpacing": 2}, {"id": "da_0158", "type": "text", "zIndex": 2, "x": 40, "y": 170, "width": 448, "height": 40, "content": "THE BOUNDARY", "fontFamily": "Special Elite", "fontSize": 28, "color": "#e8e4d9", "align": "center", "bold": true}, {"id": "da_0159", "type": "text", "zIndex": 2, "x": 40, "y": 240, "width": 448, "height": 400, "content": "National parks are fancy prison walls — containment over seams. Highways ride the strongest parts of the projection. Crown land stretches and squishes perception.\n\nBlake and Lyse weren't just HR. They were Geographers. Project Tectonic threatened to expose the redundancies in the system. The system doesn't want to be exposed.\n\n\"Cats are natural Threads,\" Karma said. \"They can see the seams. They just don't care.\"\n\nEach territory has its own sun and moon. The Earth doesn't spin. The field creates the illusion of motion.\n\nAt the Boundary: accept the lie, or break it.\n\nI've never been comfortable. I don't think I'd know what to do with comfort if I found it.", "fontFamily": "Courier Prime", "fontSize": 13, "color": "#ddd", "align": "left", "lineHeight": 1.4}, {"id": "da_0160", "type": "text", "zIndex": 3, "x": 114, "y": 680, "width": 300, "height": 40, "content": "CONTINUE TO THE WEAVE →", "action": "goto", "actionVal": "22", "fontFamily": "Special Elite", "fontSize": 14, "color": "#fff", "align": "center", "bold": true, "fill": "#bc00ff", "borderRadius": 4}], "isLocked": true, "password": "seam"}, {"id": 1000000000167, "background": "#1a0505", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0161", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "lightning", "opacity": 0.3}, {"id": "da_0162", "type": "text", "zIndex": 2, "x": 40, "y": 30, "width": 448, "height": 24, "content": "PART THREE", "fontFamily": "Courier Prime", "fontSize": 12, "color": "#ff003c", "align": "center", "lineHeight": 1.35, "letterSpacing": 6}, {"id": "da_0163", "type": "text", "zIndex": 2, "x": 40, "y": 60, "width": 448, "height": 50, "content": "THE WEAVE", "fontFamily": "Cinzel", "fontSize": 40, "color": "#e8e4d9", "align": "center", "bold": true}, {"id": "da_0164", "type": "text", "zIndex": 2, "x": 40, "y": 120, "width": 448, "height": 24, "content": "CHAPTER 10 — The Boundary", "fontFamily": "Special Elite", "fontSize": 13, "color": "#c5b358", "align": "center", "lineHeight": 1.35}, {"id": "da_0165", "type": "text", "zIndex": 2, "x": 40, "y": 160, "width": 448, "height": 440, "content": "Black SUVs on roads that don't exist. Geographers. Herding us to the Boundary where the projection is strongest.\n\nBlake offered everything back: cushy GEO middle-management, home, job — if I would un-see it.\n\n\"I've learned that my anxiety isn't a disorder. It's a detection system. My paranoia isn't pathology. It's pattern recognition. My anger isn't a problem. It's a response to a world that has been lying to me since the day I was born.\n\nI'm not broken. I've never been broken. The world is broken. And I'm going to fucking prove it.\"\n\n\"I've been livestreaming this to the Thread network.\"\n\nHeadlights behind the SUVs. Dozens of them. The Threads were coming.\n\n\"You're making a mistake,\" Blake called. \"The truth won't set you free. It'll destroy you.\"\n\n\"Maybe. But at least I'll be destroyed by the truth instead of preserved by the lie.\"", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#eee", "align": "left", "lineHeight": 1.4}, {"id": "da_0166", "type": "text", "zIndex": 4, "x": 114, "y": 640, "width": 300, "height": 44, "content": "⚡ CROSS THE BOUNDARY", "action": "vfx", "actionVal": "lightning", "fontFamily": "Orbitron", "fontSize": 14, "color": "#fff", "align": "center", "bold": true, "fill": "#ff003c", "borderRadius": 4, "animation": "pulse", "animDuration": 1.2, "animLoop": true}, {"id": "da_0167", "type": "text", "zIndex": 4, "x": 164, "y": 710, "width": 200, "height": 36, "content": "STEP THROUGH →", "action": "goto", "actionVal": "23", "fontFamily": "Special Elite", "fontSize": 14, "color": "#000", "align": "center", "bold": true, "fill": "#c5b358", "borderRadius": 4}], "bgm": "gen:horror"}, {"id": 1000000000173, "background": "#0a0a14", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0168", "type": "shader", "zIndex": 0, "x": 0, "y": 0, "width": 528, "height": 816, "shaderPreset": "galaxy", "opacity": 0.45}, {"id": "da_0169", "type": "text", "zIndex": 2, "x": 40, "y": 50, "width": 448, "height": 40, "content": "GREATER EARTH", "fontFamily": "Cinzel", "fontSize": 28, "color": "#e8e4d9", "align": "center", "bold": true}, {"id": "da_0170", "type": "text", "zIndex": 2, "x": 40, "y": 110, "width": 448, "height": 420, "content": "The Boundary felt like falling and flying at the same time. Like being unmade and remade.\n\nVast. Infinite. Territories under their own suns. The grid visible — faint lines of force, seams, hidden roads Threads had traveled for centuries.\n\n\"It's beautiful,\" Karma said.\n\"It's real,\" I said.\nZen meowed. It sounded like approval.\n\nAfter the Boundary fell, everything changed — not overnight. Most people preferred the lie. But the Threads came. Hundreds, then thousands. We mapped the seams. Updated the Devil's Atlas.\n\n\"You're happier,\" Karma said one night at a campfire on the seam.\n\"I'm not happier. I'm just... less unhappy.\"\n\"Is there a difference?\"\n\"Happiness is a destination. Less unhappy is a direction.\"", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#ddd", "align": "left", "lineHeight": 1.4}, {"id": "da_0171", "type": "panel", "zIndex": 2, "x": 40, "y": 560, "width": 448, "height": 140, "fill": "rgba(0,0,0,0.6)", "panelBorderWidth": 1, "panelBorderColor": "#c5b358", "panelRadius": 0}, {"id": "da_0172", "type": "text", "zIndex": 3, "x": 50, "y": 575, "width": 428, "height": 20, "content": "FINAL GONZO DIGRESSION", "fontFamily": "Bangers", "fontSize": 14, "color": "#e44", "align": "center", "lineHeight": 1.35}, {"id": "da_0173", "type": "text", "zIndex": 3, "x": 50, "y": 605, "width": 428, "height": 80, "content": "Zen knew all along. Cats don't believe in maps. Cats don't trust GPS. They live in the cracks between the lies.\nA warm lap and a full food bowl matter more than any map ever drawn.", "fontFamily": "EB Garamond", "fontSize": 12, "color": "#e8e4d9", "align": "center", "lineHeight": 1.35, "italic": true}], "bgm": "gen:nature"}, {"id": 1000000000181, "background": "#1a1208", "texture": "https://www.transparenttextures.com/patterns/dark-matter.png", "elements": [{"id": "da_0174", "type": "image", "zIndex": 0, "x": -40, "y": -40, "width": 250, "height": 250, "src": "/assets/devils-atlas/ink-splat33.png", "objectFit": "cover", "opacity": 0.4}, {"id": "da_0175", "type": "image", "zIndex": 0, "x": 320, "y": 550, "width": 250, "height": 250, "src": "/assets/devils-atlas/ink-splat08.png", "objectFit": "cover", "opacity": 0.35, "rotation": 180}, {"id": "da_0176", "type": "text", "zIndex": 2, "x": 40, "y": 60, "width": 448, "height": 24, "content": "EPILOGUE", "fontFamily": "Courier Prime", "fontSize": 12, "color": "#c5b358", "align": "center", "lineHeight": 1.35, "letterSpacing": 6}, {"id": "da_0177", "type": "text", "zIndex": 2, "x": 40, "y": 100, "width": 448, "height": 80, "content": "THE WEAVE\nCONTINUES", "fontFamily": "Cinzel", "fontSize": 32, "color": "#e8e4d9", "align": "center", "bold": true}, {"id": "da_0178", "type": "text", "zIndex": 2, "x": 40, "y": 210, "width": 448, "height": 360, "content": "Two years later. Campfire on the seam. Wrong stars. Real sky.\n\nA new Thread: Sarah, with an H. Anxiety. Paranoia. A body screaming for years. We'll help her. We always do.\n\nI don't have a job. I don't have a home. I have a car, a cat, and a purpose. I have Karma. I have the Threads. I have the truth.\n\nIt's not much. But it's enough.\n\n\"The world is a lie,\" I say. \"But the truth is out there. You just have to drive down the wrong road to find it.\"\n\nZen meows. She's hungry. She's always hungry.\n\nI start the engine. I put the car in gear.\n\nAnd we drive.", "fontFamily": "EB Garamond", "fontSize": 13, "color": "#ddd", "align": "left", "lineHeight": 1.4}, {"id": "da_0179", "type": "shape", "zIndex": 1, "x": 140, "y": 600, "width": 248, "height": 2, "shape": "line_h", "fill": "#c5b358", "opacity": 0.6}, {"id": "da_0180", "type": "text", "zIndex": 2, "x": 40, "y": 630, "width": 448, "height": 40, "content": "END", "fontFamily": "Cinzel", "fontSize": 28, "color": "#c5b358", "align": "center", "lineHeight": 1.35, "bold": true}, {"id": "da_0181", "type": "text", "zIndex": 2, "x": 40, "y": 700, "width": 448, "height": 50, "content": "\"Buy the ticket, take the ride.\"\n— John Smith, The Devil's Atlas", "fontFamily": "EB Garamond", "fontSize": 12, "color": "#888", "align": "center", "lineHeight": 1.35, "italic": true}]}]}
